const items = $input.all();
const form = items[0].json;

const category = form['Product Category'] || form.category || 'Area Rug';
const focus = form['Focus Area'] || form.focus || '';

// ── Decode uploaded HTML files ──────────────────────────────────────────────
let p2Content = '';
if (form['P2 Market Analysis Report']) {
  const p2Data = form['P2 Market Analysis Report'];
  if (typeof p2Data === 'string') { p2Content = p2Data; }
  else if (p2Data.data) { p2Content = Buffer.from(p2Data.data, 'base64').toString('utf8'); }
}

let p3Content = '';
if (form['P3 Competitor Analysis Report']) {
  const p3Data = form['P3 Competitor Analysis Report'];
  if (typeof p3Data === 'string') { p3Content = p3Data; }
  else if (p3Data.data) { p3Content = Buffer.from(p3Data.data, 'base64').toString('utf8'); }
}

// ── Strip HTML tags ─────────────────────────────────────────────────────────
const stripHtml = (html) => html
  .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
  .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const p2Text = stripHtml(p2Content);
const p3Text = stripHtml(p3Content);

// ── INPUT VALIDATION ────────────────────────────────────────────────────────
const validationErrors = [];
if (!p2Content || p2Text.length < 200) validationErrors.push('P2 Market Analysis Report appears empty or too short.');
if (!p3Content || p3Text.length < 200) validationErrors.push('P3 Competitor Analysis Report appears empty or too short.');
if (!p2Text.toLowerCase().includes('micro') && !p2Text.toLowerCase().includes('segment'))
  validationErrors.push('P2 report does not appear to contain micro-segment data.');
if (!p3Text.toLowerCase().includes('wayfair') || !p3Text.toLowerCase().includes('amazon'))
  validationErrors.push('P3 report does not appear to contain competitor comparison data.');

// ── PARSE P02 MICRO-SEGMENTS ─────────────────────────────────────────────────
// Strategy: find the Micro-Segments block and extract each segment's fields.
// The P02 HTML renders segments as: [Name] [tier] [description] 🎨 [colors] 🏠 [rooms]
const micro_segments = [];

const segmentPatterns = [
  {
    name: 'Textured Neutral Minimalist',
    tier: 'premium',
    price_band: '$200–$600+',
  },
  {
    name: 'Retro Abstract Geometric',
    tier: 'mid-range',
    price_band: '$50–$200',
  },
  {
    name: 'Luxury 3D Wool Abstract',
    tier: 'premium',
    price_band: '$400–$1000+',
  }
];

for (const seg of segmentPatterns) {
  const idx = p2Text.indexOf(seg.name);
  if (idx === -1) continue;

  const chunk = p2Text.slice(idx, idx + 600);

  // Extract colors (after 🎨)
  const colorMatch = chunk.match(/🎨\s*([^🏠]+)/);
  const colors = colorMatch ? colorMatch[1].trim().replace(/\s+/g, ' ') : '';

  // Extract rooms (after 🏠)
  const roomMatch = chunk.match(/🏠\s*([^💡📊🎨\n]+)/);
  const rooms = roomMatch ? roomMatch[1].trim().replace(/\s+/g, ' ') : '';

  // Extract description (text between tier label and 🎨)
  const tierIdx = chunk.indexOf(seg.tier);
  const descStart = tierIdx !== -1 ? tierIdx + seg.tier.length : seg.name.length;
  const emojiIdx = chunk.indexOf('🎨');
  const description = emojiIdx !== -1
    ? chunk.slice(descStart, emojiIdx).trim().slice(0, 300)
    : '';

  micro_segments.push({
    name: seg.name,
    tier: seg.tier,
    price_band: seg.price_band,
    color_palette: colors,
    target_rooms: rooms,
    description: description
  });
}

// Fallback: if parsing found nothing, note it clearly
const segments_parsed = micro_segments.length > 0;

// ── LIMIT TEXT FOR AI CONTEXT ────────────────────────────────────────────────
const p2Truncated = p2Text.slice(0, 12000);
const p3Truncated = p3Text.slice(0, 12000);

return [{
  json: {
    category,
    focus,
    p2_content: p2Truncated,
    p3_content: p3Truncated,
    micro_segments,         // structured objects for AI prompt
    segments_parsed,
    validation_errors: validationErrors,
    has_validation_errors: validationErrors.length > 0
  }
}];

