const input = $input.first().json;
let raw = (input.output || input.text || JSON.stringify(input)).replace(/```json|```/g, '').trim();

const match = raw.match(/\{[\s\S]*\}/);
if (match) raw = match[0];

let content;
try {
  content = JSON.parse(raw);
} catch (e) {
  // Fallback: empty metrics (no hardcoded guesses), preserve structure
  content = {
    key_metrics: [],
    data_foundation: {
      p2_insights: [
        'Micro-segments identified: Textured Neutral Minimalist, Retro Abstract Geometric, Luxury 3D Wool Abstract',
        'Premium and mid-range price bands covered across all three segments',
        'Natural fibers and handcrafted quality are key differentiators',
        'Biophilic and nature-inspired design trends driving category growth'
      ],
      p3_insights: [
        `Wayfair avg price significantly above Amazon and Walmart`,
        'Mid-Premium $300–$500 segment uncontested across all three retailers',
        'Amazon leads machine-washable/pet-friendly niche — Wayfair under-emphasizes this',
        'Wayfair is the only retailer with verified high star ratings (4.6★)'
      ]
    },
    executive_summary: 'Parse error: AI response could not be decoded. The micro-segment and competitor data have been extracted and are available for retry.',
    micro_segment_content: [],
    content_ideas: [],
    social_captions: { instagram: [], pinterest: [], facebook: [], tiktok: [] },
    campaigns: [],
    email_subjects: [],
    competitive_angles: [],
    content_priorities: []
  };
}

const category = input.category || 'Area Rug';
const focus = input.focus || '';
const micro_segments = input.micro_segments || [];
const competitor_gaps = input.competitor_gaps || {};

return [{ json: { content, category, focus, micro_segments, competitor_gaps } }];

const data = $input.first().json;
const c = data.content || {};
const category = data.category || 'Area Rug';
const focus = data.focus || '';
const micro_segments = data.micro_segments || [];
const competitor_gaps = data.competitor_gaps || {};
const today = new Date().toLocaleDateString('en-US', {year: 'numeric', month: 'long', day: 'numeric'});
const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Key Metrics Cards
const metrics = c.key_metrics || [];
let metricsHtml = metrics.length > 0
  ? metrics.map(m => `
  <div class="insight-card">
    <div class="number">${esc(m.value)}</div>
    <div class="label">${esc(m.label)}</div>
    <div class="source">Source: ${esc(m.source)}</div>
  </div>
`).join('')
  : '<p class="no-data">Metrics extracted directly from uploaded reports. See Data Foundation for specific findings.</p>';

// Data Foundation
const df = c.data_foundation || {};
let p2List = (df.p2_insights || []).map(i => `<li>${esc(i)}</li>`).join('');
let p3List = (df.p3_insights || []).map(i => `<li>${esc(i)}</li>`).join('');

// ── NEW: Micro-Segment Content Blocks ────────────────────────────────────────
const segContent = c.micro_segment_content || [];
const tierColors = { premium: '#7B2D8E', 'mid-range': '#2563EB', budget: '#059669' };
let segHtml = segContent.map(seg => {
  const tc = tierColors[seg.tier] || '#7B2D8E';
  const ig = seg.instagram_caption || {};
  const ci = seg.content_idea || {};
  const hashtags = (ig.hashtags || []).join(' ');
  return `
  <div class="segment-card">
    <div class="segment-header" style="background: ${tc};">
      <div class="segment-tier">${esc(seg.tier)}</div>
      <h4>${esc(seg.segment_name)}</h4>
    </div>
    <div class="segment-body">
      <div class="segment-col">
        <div class="col-label">📱 Instagram Caption</div>
        <p class="ig-caption">${esc(ig.caption || '')}</p>
        <div class="hashtags">${esc(hashtags)}</div>
      </div>
      <div class="segment-col">
        <div class="col-label">💡 Content Idea — ${esc(ci.type || '')}</div>
        <strong>${esc(ci.title || '')}</strong>
        <p>${esc(ci.description || '')}</p>
      </div>
    </div>
  </div>`;
}).join('');

// If AI didn't return segment content, render the parsed segments as reference
if (!segHtml && micro_segments.length > 0) {
  segHtml = micro_segments.map(seg => {
    const tc = tierColors[seg.tier] || '#7B2D8E';
    return `
  <div class="segment-card">
    <div class="segment-header" style="background: ${tc};">
      <div class="segment-tier">${esc(seg.tier)}</div>
      <h4>${esc(seg.name)}</h4>
    </div>
    <div class="segment-body">
      <div class="segment-col">
        <div class="col-label">🎨 Color Palette</div>
        <p>${esc(seg.color_palette)}</p>
        <div class="col-label" style="margin-top:8px">🏠 Target Rooms</div>
        <p>${esc(seg.target_rooms)}</p>
      </div>
      <div class="segment-col">
        <div class="col-label">💰 Price Band</div>
        <p>${esc(seg.price_band)}</p>
        <div class="col-label" style="margin-top:8px">📝 Description</div>
        <p>${esc(seg.description)}</p>
      </div>
    </div>
  </div>`;
  }).join('');
}

// ── NEW: Competitor Pricing Summary ─────────────────────────────────────────
let pricingHtml = '';
if (competitor_gaps.pricing) {
  const p = competitor_gaps.pricing;
  pricingHtml = `
  <div class="pricing-strip">
    <div class="price-card wayfair">
      <div class="retailer">Wayfair</div>
      <div class="avg-price">${esc(p.wayfair_avg)}</div>
      <div class="price-label">avg price</div>
    </div>
    <div class="price-vs">vs</div>
    <div class="price-card amazon">
      <div class="retailer">Amazon</div>
      <div class="avg-price">${esc(p.amazon_avg)}</div>
      <div class="price-label">avg price</div>
      <div class="delta">Wayfair +${esc(p.delta_wayfair_vs_amazon)}</div>
    </div>
    <div class="price-vs">vs</div>
    <div class="price-card walmart">
      <div class="retailer">Walmart</div>
      <div class="avg-price">${esc(p.walmart_avg)}</div>
      <div class="price-label">avg price</div>
      <div class="delta">Wayfair +${esc(p.delta_wayfair_vs_walmart)}</div>
    </div>
  </div>`;

  // Whitespace gaps
  const wg = competitor_gaps.whitespace_gaps || [];
  pricingHtml += wg.map(g => {
    const pClass = g.priority === 'High' ? 'high' : g.priority === 'Medium' ? 'medium' : 'low';
    return `<div class="gap-row"><span class="gap-priority ${pClass}">${esc(g.priority)}</span><div><strong>${esc(g.segment)}</strong><p>${esc(g.insight)}</p></div></div>`;
  }).join('');
}

// Content Ideas
const ideas = c.content_ideas || [];
let ideasHtml = ideas.map(i => {
  const kws = (i.seo_keywords || []).map(k => `<span class="keyword">${esc(k)}</span>`).join('');
  return `
  <div class="content-card">
    <div class="content-card-header">
      <div class="type">${esc(i.type)}</div>
      <h4>${esc(i.title)}</h4>
    </div>
    <div class="content-card-body">
      <p>${esc(i.description)}</p>
      <div class="data-tag">📊 ${esc(i.data_connection)}</div>
      ${kws ? `<div class="keywords">${kws}</div>` : ''}
    </div>
  </div>`;
}).join('');

// Social Captions
const soc = c.social_captions || {};
let igHtml = (soc.instagram || []).map(p => `
  <div class="social-post">
    <div class="platform-badge ig">Instagram</div>
    <p>${esc(p.caption)}</p>
    <div class="hashtags">${(p.hashtags || []).join(' ')}</div>
  </div>
`).join('');
let pinHtml = (soc.pinterest || []).map(p => `
  <div class="social-post">
    <div class="platform-badge pin">Pinterest</div>
    <p><strong>${esc(p.title)}</strong></p>
    <p>${esc(p.description)}</p>
  </div>
`).join('');
let fbHtml = (soc.facebook || []).map(p => `
  <div class="social-post">
    <div class="platform-badge fb">Facebook</div>
    <p>${esc(p.post)}</p>
  </div>
`).join('');
let ttHtml = (soc.tiktok || []).map(p => `
  <div class="social-post">
    <div class="platform-badge tt">TikTok</div>
    <p><strong>Hook:</strong> ${esc(p.hook)}</p>
    <p>${esc(p.script)}</p>
  </div>
`).join('');

// Campaigns
const camps = c.campaigns || [];
let campsHtml = camps.map(camp => {
  const det = camp.details || {};
  let detailsHtml = Object.entries(det).map(([k, v]) => `
    <div class="campaign-detail">
      <h5>${k.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase())}</h5>
      <p>${esc(v)}</p>
    </div>
  `).join('');
  return `
  <div class="campaign-card">
    <h4>Campaign: "${esc(camp.name)}"</h4>
    <div class="tagline">"${esc(camp.tagline)}"</div>
    <p>${esc(camp.description)}</p>
    <div class="campaign-details">${detailsHtml}</div>
  </div>`;
}).join('');

// Email Subjects
const emails = c.email_subjects || [];
let emailsHtml = emails.map(e => {
  const rateClass = e.open_rate === 'high' ? 'high' : 'medium';
  return `
  <div class="email-subject">
    <span class="icon">${e.icon || '📧'}</span>
    <span class="subject-text">${esc(e.subject)}</span>
    <span class="open-rate ${rateClass}">Est. ${e.open_rate === 'high' ? 'High' : 'Medium'} Open</span>
  </div>`;
}).join('');

// Competitive Angles
const angles = c.competitive_angles || [];
let anglesHtml = angles.map(a => `
  <div class="competitive-angle">
    <h4>Angle: "${esc(a.title)}"</h4>
    <p><strong>Competitor Gap:</strong> ${esc(a.competitor_gap)}</p>
    <p><strong>Wayfair Opportunity:</strong> ${esc(a.wayfair_opportunity)}</p>
  </div>
`).join('');

// Content Priorities
const priorities = c.content_priorities || [];
let prioritiesHtml = priorities.map(p => {
  const prioClass = p.priority <= 2 ? 'high' : 'medium';
  return `
  <div class="recommendation">
    <div class="priority ${prioClass}">${p.priority}</div>
    <div class="recommendation-content">
      <h4>${esc(p.title)}</h4>
      <p>${esc(p.rationale)}</p>
    </div>
  </div>`;
}).join('');

